<?php
header('Content-Type: application/json; charset=utf-8');if(!defined('BASE_DIR'))define('BASE_DIR',realpath(__DIR__.'/../..'));
require_once BASE_DIR.'/config/paths.php';require_once CONFIG_DIR.'/conexion.php';require_once CONFIG_DIR.'/validacion.php';require_once CONFIG_DIR.'/csrf.php';require_once CONFIG_DIR.'/seguridad.php';require_once CONFIG_DIR.'/clasificacion_documental.php';csrf_exigir();
function decidirClasificacionJson(int $code,string $message):void{http_response_code($code);echo json_encode(['status'=>$code<400?'ok':'error','message'=>$message],JSON_UNESCAPED_UNICODE);exit;}
$user=seguridadUsuarioActual($conn);if(!seguridadTieneRol($user,[1,2,4]))decidirClasificacionJson(403,'No tienes permiso para validar propuestas.');$proposal=(int)($_POST['id_propuesta']??0);$decision=(string)($_POST['decision']??'');$reason=trim((string)($_POST['motivo']??''));if($proposal<1||mb_strlen($reason)>1000)decidirClasificacionJson(400,'La solicitud no es válida.');
$st=$conn->prepare('SELECT e.id_evidencia,e.id_docente,e.ocultar FROM propuestas_clasificacion_documental p JOIN evidencia_aplicaciones_academicas a ON a.id_aplicacion=p.id_aplicacion JOIN evidencias e ON e.id_evidencia=a.id_evidencia WHERE p.id_propuesta=?');$st->bind_param('i',$proposal);$st->execute();$e=$st->get_result()->fetch_assoc();$st->close();if(!$e||(int)$e['ocultar']!==0||!seguridadPuedeEditarEvidencia($user,$e))decidirClasificacionJson(403,'No tienes permiso para esta propuesta.');
$name=trim((string)($_SESSION['SESUSUARIO']??'').' '.(string)($_SESSION['APELLIDO']??''));try{clasificacionDecidir($conn,$proposal,(int)$user['id_usuario'],$name,$decision,$reason);decidirClasificacionJson(200,'La propuesta quedó registrada como validación humana; no es un dictamen oficial.');}catch(Throwable $ex){error_log('ODEA classification decision failed proposal='.$proposal.' code='.get_class($ex));decidirClasificacionJson(422,'No se pudo guardar la validación.');}
